ALTER TABLE "organisation_onboarding" ADD CONSTRAINT "organisation_onboarding_mobile_otp_ck" CHECK (("organisation_onboarding"."pending_admin_mobile" is null and "organisation_onboarding"."admin_mobile_otp_hash" is null and "organisation_onboarding"."admin_mobile_otp_expires_at" is null and "organisation_onboarding"."admin_mobile_otp_attempts" is null and "organisation_onboarding"."admin_mobile_otp_sent_at" is null) or ("organisation_onboarding"."pending_admin_mobile" ~ '^\+614[0-9]{8}$' and length("organisation_onboarding"."admin_mobile_otp_hash") = 64 and "organisation_onboarding"."admin_mobile_otp_expires_at" is not null and "organisation_onboarding"."admin_mobile_otp_attempts" is not null and "organisation_onboarding"."admin_mobile_otp_attempts" >= 0 and "organisation_onboarding"."admin_mobile_otp_attempts" <= 5 and "organisation_onboarding"."admin_mobile_otp_sent_at" is not null));